package blockquotes

import (
	"bytes"
	"testing"

	qt "github.com/frankban/quicktest"
	"github.com/gohugoio/hugo/markup/goldmark/internal/render"
)

func TestResolveGitHubAlert(t *testing.T) {
	t.Parallel()

	c := qt.New(t)

	tests := []struct {
		input    string
		expected string
	}{
		{
			input:    "[!NOTE]",
			expected: "note",
		},
		{
			input:    "[!WARNING]",
			expected: "warning",
		},
		{
			input:    "[!TIP]",
			expected: "tip",
		},
		{
			input:    "[!IMPORTANT]",
			expected: "important",
		},
		{
			input:    "[!CAUTION]",
			expected: "caution",
		},
		{
			input:    "[!FOO]",
			expected: "",
		},
	}

	r := &htmlRenderer{
		alertRe:      gitHubAlertRe,
		fallbackType: typeRegular,
	}

	for _, test := range tests {
		ctx := &render.Context{
			BufWriter: &render.BufWriter{Buffer: bytes.NewBufferString("<p>" + test.input)},
		}
		ctx.PushPos(0)
		bqctx := &blockquoteContext{}
		c.Assert(r.resolveGitHubAlert(render.NewBlockquoteCapture(ctx), bqctx), qt.Equals, test.expected)
	}
}

